import assert from 'node:assert/strict';
import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {chapterCollections,chapterHash,practiceChapters} from '../lib/practice-chapters.ts';
import {exerciseSetHelp} from '../lib/content-levels.ts';
import {learningGoalFor} from '../lib/learning-goals.ts';
const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_INFO_OUTPUT||'outputs/info-header-20261101/local';mkdirSync(out,{recursive:true});
const activities=['content-woordpakketten','sound-path','sentences','text-question','dialogues'],cases=activities.map(activity=>{
 const rows=chapterCollections(activity),row=activity==='content-woordpakketten'?rows.find(r=>r.id==='content:woordpakketten:word-self:b1:b1:choice'):activity==='dialogues'?rows.find(r=>r.id==='klink-dialogue-32f962399de8f4c3')||rows[0]:activity==='text-question'?rows.find(r=>r.level==='a1')||rows[0]:rows[0],es=row.contentUrl?JSON.parse(readFileSync('public'+row.contentUrl)).exercises:row.exercises,e=es[0],chapter=practiceChapters.find(c=>c.activities.includes(activity)).id;
 return{activity,row,e,goal:learningGoalFor(e),route:'/'+chapterHash({chapter,activity,collection:row.id,level:row.level,help:exerciseSetHelp(es)})};
});writeFileSync(out+'/examples.json',JSON.stringify(cases.map(({activity,route,goal})=>({activity,route,goal})),null,2)+'\n');
const checks=[],errors=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{for(const[width,height]of[[1686,829],[390,844],[320,568]])for(const theme of['light','dark'])for(const c of cases){
 const p=await b.newPage({viewport:{width,height},hasTouch:true,colorScheme:theme});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>localStorage.setItem('klink.header.retention','kept'));await p.goto(base+c.route);const root=p.locator('[data-exercise-id]');await root.waitFor();await p.evaluate(theme=>document.documentElement.setAttribute('data-theme',theme),theme);const id=await root.getAttribute('data-exercise-id'),header=p.locator('.cp-exercise-record-head'),trigger=header.getByRole('button',{name:'Over deze oefening',exact:true});await trigger.waitFor();assert.equal(await p.locator('.cp-exercise-stage').getByRole('button',{name:'Over deze oefening',exact:true}).count(),0);assert(await trigger.evaluate(e=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.width>=44&&r.height>=44;}));
 if(c.activity==='content-woordpakketten'){
  const correct=c.e.contentTask.options.find(o=>c.e.contentTask.correctOptionIds.includes(o.id));await p.getByRole('button',{name:correct.text,exact:true}).tap();const selected=p.getByRole('button',{name:correct.text,exact:true});assert.equal(await selected.getAttribute('aria-pressed'),'true');assert((await selected.getAttribute('class')).includes('selected'));await p.waitForTimeout(250);assert(await selected.evaluate(e=>getComputedStyle(e).backgroundColor!==getComputedStyle(e.parentElement.querySelector('[aria-pressed="false"]')).backgroundColor));const check=p.getByRole('button',{name:'Controleer',exact:true});assert(await check.isEnabled());if(width<600)await check.scrollIntoViewIfNeeded();assert(await check.evaluate(e=>{const r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return r.top>=0&&r.bottom<=innerHeight&&(hit===e||e.contains(hit));}));
 }
 if(engine==='chromium'&&theme==='light'&&width!==320)await p.screenshot({path:`${out}/${c.activity}-${width}-task.png`});
 await trigger.press('Enter');const dialog=p.getByRole('dialog');await dialog.waitFor();assert.equal(await dialog.locator('[data-learning-goal]').getAttribute('data-learning-goal'),c.goal.id);assert.deepEqual(await dialog.locator('.cp-learning-goal-labels span').allTextContents(),c.goal.displayLabels);assert.equal(await dialog.locator('.cp-learner-goal p').innerText(),c.goal.learnerText);assert(await dialog.evaluate(e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&r.left>=0&&r.right<=innerWidth;}));
 if(engine==='chromium'&&theme==='light'&&width!==320)await p.screenshot({path:`${out}/${c.activity}-${width}-info.png`});await p.keyboard.press('ArrowRight');assert.equal(await root.getAttribute('data-exercise-id'),id);await p.keyboard.press('Escape');await dialog.waitFor({state:'hidden'});assert(await trigger.evaluate(e=>e===document.activeElement));
 if(c.activity==='content-woordpakketten'){
  const selected=p.locator('.cp-content-task .cp-choice-grid > button[aria-pressed="true"]');assert.equal(await selected.count(),1);await p.getByRole('button',{name:'Controleer',exact:true}).tap();assert(await p.locator('[data-practice-next]').isEnabled());if(engine==='chromium'&&theme==='light')await p.screenshot({path:`${out}/answer-${width}.png`});await p.locator('[data-practice-next]').press('Enter');assert.notEqual(await root.getAttribute('data-exercise-id'),id);
 }
 assert.equal(await p.evaluate(()=>localStorage.getItem('klink.header.retention')),'kept');checks.push({engine,width,height,theme,activity:c.activity,goal:c.goal.id,labels:c.goal.displayLabels,infoInHeader:true,oneInfoButton:true,dialogFits:true,focusRestored:true,selectionVisible:c.activity==='content-woordpakketten'?true:undefined,checkReachable:c.activity==='content-woordpakketten'?true:undefined,answerAndNext:c.activity==='content-woordpakketten'?true:undefined,storagePreserved:true});await p.close();
 }}finally{await b.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors},null,2)+'\n');}}
assert.equal(checks.length,60);assert.deepEqual(errors,[]);console.log('PASS 60 header/goal/layout checks, including 12 real selection-check-next flows');
